// Synthetic physical bytes (not ROM data): the 4411e..4439e WORD table read by 443d2 and the e583c LONG table read by e57a8.
const char* const SYN_SINE="";
const char* const SYN_SEGMENTS="0010e9000010e980";
// ---- generated tables (end)
const unsigned int FIXTURE_COUNT=sizeof(FIXTURES)/sizeof(FIXTURES[0]);
const unsigned int BLOCK_COUNT=sizeof(BLOCKS)/sizeof(BLOCKS[0]);
// Contract lists: FLOW_ONLY (32), carry consumers (2), known-carry producers (Clear 3, Set 1), bundled BNE PC (1).
const std::uint32_t FLOW[]={0x396e,0x39f8,0x3a70,0x3a7a,0x3a7e,0x3a80,0x8ecc,0x8efe,0x8f6a,0xe50b4,0xe50c0,0xe511e,0xe5120,0xe512a,
 0xe5170,0xe519e,0xe51b4,0xe51d8,0xe51ee,0xe5226,0xe5246,0xe527a,0xe5286,0xe528c,0xe5670,0xe567e,0xe56a0,0xe56ac,0xe56b0,0xe56be,
 0xe57f0,0xe583a};
